"def test_claim_users_with_mixed_identifiers(enterprise, enterprise_mocks):
    users = {
        'usrFakeUserId1': 'managed',
        'someone@example.com': 'unmanaged',
        'usrFakeUserId2': 'unmanaged',
        'another@example.com': 'managed'
    }
    result = enterprise.claim_users(users)

    assert isinstance(result, ManageUsersResponse)
    assert enterprise_mocks.claim_users.call_count == 1

    expected_payload = {
        'users': [
            {'id': 'usrFakeUserId1', 'state': 'managed'},
            {'email': 'someone@example.com', 'state': 'unmanaged'},
            {'id': 'usrFakeUserId2', 'state': 'unmanaged'},
            {'email': 'another@example.com', 'state': 'managed'}
        ]
    }
    assert enterprise_mocks.claim_users.last_request.json() == expected_payload"

"import urllib.parse

@pytest.mark.parametrize('test_input, expected', [
    ('https://example.com/path', urllib.parse.SplitResult(scheme='https', netloc='example.com', path='/path', query='', fragment='')),
    ('//example.com/path', urllib.parse.SplitResult(scheme='', netloc='', path='//example.com/path', query='', fragment='')),
    ('a' * 101, urllib.parse.SplitResult(scheme='', netloc='', path='a' * 100, query='', fragment='')),
    ('normal/path', urllib.parse.SplitResult(scheme='', netloc='', path='normal/path', query='', fragment=''))
])
def test_split_request_uri_new_cases(test_input, expected):
    assert util.split_request_uri(test_input) == expected"

"def test_delete_non_enterprise_base(api, base, monkeypatch):
    """
    Test that Base.delete() raises an exception for non-enterprise plans (404 response).
    """
    class MockResponse:
        def __init__(self, status_code):
            self.status_code = status_code

    def mock_delete(url):
        return MockResponse(404)

    monkeypatch.setattr(api, 'delete', mock_delete)

    with pytest.raises(Exception) as excinfo:
        base.delete()

    assert "Base.delete() requires an enterprise billing plan" in str(excinfo.value)"
